    threeInsideDownDesc: 'Vela alcista, luego harami bajista dentro de ella, luego vela de confirmación que cierra por debajo de la primera. Fuerte reversión bajista.',
    eveningDojiStarName: 'Estrella Doji de la Tarde',
    eveningDojiStarDesc: 'Reversión bajista de tres velas: vela alcista, Doji con gap al alza, luego vela bajista. Más fuerte que la Estrella de la Tarde normal.',
    bearishMarubozuName: 'Marubozu Bajista',
    bearishMarubozuDesc: 'Vela bajista completa sin mechas. Muestra una fuerte presión vendedora desde la apertura hasta el cierre sin participación compradora.',
    bearishKickerName: 'Kicker Bajista',
    bearishKickerDesc: 'Gap bajista desde una vela alcista a una vela bajista. Una de las señales de reversión bajista más poderosas en el análisis de velas.',
    tweezersTopName: 'Pinzas Techo',
    tweezersTopDesc: 'Dos velas consecutivas con máximos idénticos. Señal de fuerte resistencia e interés vendedor en ese nivel de precio.',
    // Extended Candlestick Patterns - Neutral
    longLeggedDojiName: 'Doji de Piernas Largas',
    longLeggedDojiDesc: 'Doji con mechas muy largas en ambos extremos y un cuerpo diminuto. Muestra indecisión extrema con alta volatilidad en ambas direcciones.',
    highWaveName: 'Ola Alta',
    highWaveDesc: 'Serie de velas con mechas muy largas en ambas direcciones y cuerpos pequeños. Señal de caos de mercado e indecisión extrema.',

    // Additional Chart Patterns - ES
    ascTriangleName: 'Triángulo Ascendente',
    ascTriangleDesc: 'Patrón de continuación alcista con línea de resistencia plana y línea de soporte ascendente.',
    descTriangleName: 'Triángulo Descendente',
    descTriangleDesc: 'Patrón de continuación bajista con línea de soporte plana y línea de resistencia descendente.',
    bullFlagName: 'Bandera Alcista',
    bullFlagDesc: 'Patrón de continuación a corto plazo después de fuerte tendencia alcista, mostrando consolidación antes de continuar al alza.',
    bearFlagName: 'Bandera Bajista',
    bearFlagDesc: 'Patrón de continuación a corto plazo después de fuerte tendencia bajista, mostrando consolidación antes de continuar a la baja.',
    bullPennantName: 'Banderín Alcista',
    bullPennantDesc: 'Patrón de continuación simétrico en tendencia alcista, similar a una pequeña bandera.',
    bearPennantName: 'Banderín Bajista',
    bearPennantDesc: 'Patrón de continuación simétrico en tendencia bajista, similar a una pequeña bandera.',
    ascChannelName: 'Canal Ascendente',
